5	/**
6	 * Formats an owner's membership number as '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the last two
7	 * digits of the {@link FiscalYear fiscal year} of the registration date, e.g. 'NSW-1A2B3C4D-M26'.
8	 */
9	public final class MembershipNumber {
10	
11	    private MembershipNumber() {
12	    }
13	
14	    /**
15	     * The membership number for {@code owner}, or {@code null} when the owner or the customer code or
16	     * registration date it is derived from is {@code null}.
17	     */
18	    public static String of(Owner owner) {
19	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
20	            return null;
21	        }
22	        return String.format("%s-M%02d", owner.getCustomerCode(),
23	                FiscalYear.of(owner.getRegistrationDate()) % 100);
24	    }
25	}
