1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year calendar rules. The fiscal year starts on 1 July and is named by the calendar year it
8	 * ends in, so a date on or after 1 July belongs to the next year's fiscal year (e.g. 2025-07-01 and
9	 * 2026-06-30 both fall in fiscal year 2026). Pure date arithmetic with no dependency on other state,
10	 * so it is a shared helper rather than a step.
11	 */
12	public final class FiscalYear {
13	
14	    /** The calendar month the fiscal year starts in. */
15	    public static final Month START_MONTH = Month.JULY;
16	
17	    private FiscalYear() {
18	    }
19	
20	    /** The fiscal year (named by the calendar year it ends in) that contains {@code date}. */
21	    public static int of(LocalDate date) {
22	        return date.getMonthValue() >= START_MONTH.getValue() ? date.getYear() + 1 : date.getYear();
23	    }
24	
25	    /** The 'FY&lt;YY&gt;' label for {@code date}, where YY is the last two digits of its fiscal year. */
26	    public static String label(LocalDate date) {
27	        return String.format("FY%02d", of(date) % 100);
28	    }
29	}
