5	/**
6	 * The owner's current primary identifier — the single value that identifies an owner across the
7	 * system. Today that is the {@link CustomerCode customerCode}; when identities are unified this will
8	 * resolve to the memberId instead. Callers that record "the primary identifier" (such as the
9	 * owner-created audit event) go through here, so the switch is a one-line change confined to this
10	 * class rather than spread across every consumer.
11	 */
12	public final class PrimaryIdentifier {
13	
14	    private PrimaryIdentifier() {
15	    }
16	
17	    /** The owner's current primary identifier, or {@code null} when the owner has none. */
18	    public static String of(Owner owner) {
19	        return owner.getCustomerCode();
20	    }
21	}
