1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * An owner's segment, formatted {@code <TIER>_<AREA>}. The tier is {@code PREMIUM} when the owner's
5	 * membership level (see {@link MembershipLevel}) is 3 or more, otherwise {@code STANDARD}. The area
6	 * is {@code METRO} when the owner's locality is a known region (see {@link CityRegion#isKnown(String)}),
7	 * otherwise {@code REGIONAL}. Composed at response time from the already-derived membership level and
8	 * locality, so it is derived rather than stored on the entity.
9	 */
10	public enum OwnerSegment {
11	
12	    PREMIUM_METRO,
13	
14	    PREMIUM_REGIONAL,
15	
16	    STANDARD_METRO,
17	
18	    STANDARD_REGIONAL;
19	
20	    /** The smallest membership level that counts as the {@code PREMIUM} tier. */
21	    private static final int PREMIUM_LEVEL = 3;
22	
23	    /**
24	     * The segment for the given {@code membershipLevel} (see {@link MembershipLevel}) and
25	     * {@code locality} (a region, see {@link CityRegion}). A {@code null} membership level is treated
26	     * as below the premium threshold.
27	     */
28	    public static OwnerSegment of(Integer membershipLevel, String locality) {
29	        boolean premium = membershipLevel != null && membershipLevel >= PREMIUM_LEVEL;
30	        boolean metro = CityRegion.isKnown(locality);
31	        if (premium) {
32	            return metro ? PREMIUM_METRO : PREMIUM_REGIONAL;
33	        }
34	        return metro ? STANDARD_METRO : STANDARD_REGIONAL;
35	    }
36	}
