3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.CustomerCode;
10	
11	/**
12	 * Guarantees the assigned customerCode is unique across owners. When the code computed by
13	 * {@link AssignCustomerCode} already belongs to an existing owner, it appends {@code -<n>} with the
14	 * smallest {@code n} of 2 or more that makes it unique (see {@link CustomerCode#dedupe}). Runs before
15	 * {@link SaveOwner}, so the owner being created is not yet persisted and cannot collide with itself.
16	 * Mutates the built {@link Owner} in place.
17	 */
18	public class DeduplicateCustomerCode {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        Set<String> existing = new HashSet<>();
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (other.getCustomerCode() != null) {
24	                existing.add(other.getCustomerCode());
25	            }
26	        }
27	        owner.setCustomerCode(CustomerCode.dedupe(owner.getCustomerCode(), existing));
28	    }
29	}
