1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.util.Sha256;
5	import org.springframework.samples.petclinic.util.Soundex;
6	
7	/**
8	 * A derived, opaque token summarising an owner's contact identity: the SHA-256 hex of the canonical
9	 * telephone, the canonical email (empty when absent) and the {@link Soundex} of the last name, joined
10	 * by '|'. {@link org.springframework.samples.petclinic.mapper.OwnerMapper} returns it on the response
11	 * so a client can compare owners at a glance, and the create pipeline's duplicate detection keys off
12	 * it directly (see {@link EnsureUniqueIdentity}). Not a pipeline step, so it exposes plain helpers.
13	 */
14	public final class IdentityKey {
15	
16	    private IdentityKey() {
17	    }
18	
19	    /** The identity key of an existing or freshly built owner. */
20	    public static String forOwner(Owner owner) {
21	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
22	    }
23	
24	    /**
25	     * Builds the identity key from its parts: the SHA-256 hex over the telephone in canonical E.164
26	     * form (see {@link TelephoneNormalizer}), the email lower-cased or empty when absent or blank (see
27	     * {@link EmailNormalizer}) and the {@link Soundex} of the last name, separated by '|'.
28	     */
29	    public static String of(String telephone, String email, String lastName) {
30	        return Sha256.hex(normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|" + Soundex.of(lastName));
31	    }
32	
33	    private static String normalizeTelephone(String telephone) {
34	        String e164 = TelephoneNormalizer.toE164(telephone);
35	        return e164 == null ? orEmpty(telephone) : e164;
36	    }
37	
38	    private static String normalizeEmail(String email) {
39	        return (email == null || email.isBlank()) ? "" : EmailNormalizer.normalize(email);
40	    }
41	
42	    private static String orEmpty(String value) {
43	        return value == null ? "" : value;
44	    }
45	}
