3	/**
4	 * Immutable structured record of an owner creation, emitted to the {@code AUDIT} log alongside the
5	 * human-readable audit line. Each event carries a process-wide monotonically increasing
6	 * {@code seq}, the owner's generated {@code ownerId}, its current primary identifier and the
7	 * membership level, under the {@code OWNER_CREATED} event type.
8	 *
9	 * <p>The {@code primaryIdentifier} is whatever identifies the owner today — the customerCode — and
10	 * whatever replaces it later (the memberId). It is serialized under the {@code customerCode} key
11	 * while the customerCode is primary; that key tracks the identifier when it is unified into the
12	 * memberId.
13	 */
14	public record OwnerCreatedEvent(long seq, Integer ownerId, String primaryIdentifier, Integer membershipLevel) {
15	
16	    /** The event type discriminator carried in the serialized form. */
17	    public static final String EVENT = "OWNER_CREATED";
18	
19	    /** Renders the event as a compact JSON object with fields in the documented order. */
20	    public String toJson() {
21	        return "{"
22	                + "\"seq\":" + seq
23	                + ",\"ownerId\":" + ownerId
24	                + ",\"customerCode\":" + jsonString(primaryIdentifier)
25	                + ",\"membershipLevel\":" + membershipLevel
26	                + ",\"event\":" + jsonString(EVENT)
27	                + "}";
28	    }
29	
30	    /** A JSON string literal for {@code value}, or the bare {@code null} literal when absent. */
31	    private static String jsonString(String value) {
32	        if (value == null) {
33	            return "null";
34	        }
35	        StringBuilder escaped = new StringBuilder("\"");
36	        for (int i = 0; i < value.length(); i++) {
37	            char c = value.charAt(i);
38	            if (c == '"' || c == '\\') {
39	                escaped.append('\\');
40	            }
41	            escaped.append(c);
42	        }
43	        return escaped.append('"').toString();
44	    }
45	}
