139	     * The owner's membership level (see {@link MembershipLevel}): the {@link #membershipPoints(Owner)
140	     * membership points} banded into a number from 1 to 4 (1 for 0-1 points, 2 for 2-3, 3 for 4-5,
141	     * 4 for 6 or more), then held down to the owner's household ceiling
142	     * ({@link Owner#getMembershipLevelCap()}) captured at creation. With no ceiling the banded level
143	     * stands.
144	     */
145	    default Integer membershipLevel(Owner owner) {
146	        Integer level = MembershipLevel.forPoints(MembershipPoints.of(owner));
147	        Integer cap = owner == null ? null : owner.getMembershipLevelCap();
148	        return level != null && cap != null ? Math.min(level, cap) : level;
149	    }
150	
151	    /**
152	     * The owner's segment (see {@link OwnerSegment}), formatted '&lt;TIER&gt;_&lt;AREA&gt;': TIER is
153	     * 'PREMIUM' when the owner's {@link #membershipLevel(Owner) membership level} is 3 or more, else
154	     * 'STANDARD'; AREA is 'METRO' when the owner's {@link #locality(Owner) locality} is a known region
155	     * (NSW, VIC or QLD), else 'REGIONAL'.
156	     */
157	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
158	        if (owner == null) {
159	            return null;
160	        }
161	        OwnerSegment segment = OwnerSegment.of(membershipLevel(owner), locality(owner));
162	        return OwnerDto.OwnerSegmentEnum.valueOf(segment.name());
163	    }
