167	     * address is present, otherwise 'PHONE'.
168	     */
169	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
170	        ContactPreference preference = ContactPreference.of(owner);
171	        return preference == null ? null : OwnerDto.ContactPreferenceEnum.valueOf(preference.name());
172	    }
