176	     * household id joined by '|'. A read-only summary of the owner's contact identity; duplicate
177	     * detection itself keys off the household id.
178	     */
179	    default String identityKey(Owner owner) {
180	        return owner == null ? null : IdentityKey.forOwner(owner);
181	    }
182	
183	    /**
