package org.springframework.samples.petclinic.util;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Shared SHA-256 hex helper. A pure function of its input with no dependency on other owners, used
 * wherever the application needs a stable, opaque token derived from a value (the region-and-hash
 * customerCode in {@link CustomerCode}, the household id in
 * {@link org.springframework.samples.petclinic.rest.function.owner.HouseholdNormalizer}).
 */
public final class Sha256 {

    private Sha256() {
    }

    /** The full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    public static String hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** The first {@code length} upper-case hex characters of the SHA-256 of {@code value}. */
    public static String prefix(String value, int length) {
        return hex(value).substring(0, length).toUpperCase();
    }
}

package org.springframework.samples.petclinic.util;

/**
 * Computes the Luhn check digit over the decimal digits contained in a value, ignoring any
 * non-digit characters (such as the separators in a customer code). A pure function of the value,
 * so it is derived at response time rather than stored on the entity.
 */
public final class CheckDigit {

    private CheckDigit() {
    }

    /**
     * The Luhn check digit (0-9) over the digits in {@code value}, or {@code null} when
     * {@code value} is {@code null}.
     */
    public static Integer of(String value) {
        if (value == null) {
            return null;
        }
        int sum = 0;
        boolean doubling = true;
        for (int i = value.length() - 1; i >= 0; i--) {
            char c = value.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int digit = c - '0';
            if (doubling) {
                digit *= 2;
                if (digit > 9) {
                    digit -= 9;
                }
            }
            sum += digit;
            doubling = !doubling;
        }
        return (10 - (sum % 10)) % 10;
    }
}

